-- ============================================================
-- BANCO DE DADOS: Sistema de Gestão de Itinerários
-- Município: São Roque / SP  |  Vigência: 27/11/2022
-- Operadora: Jundia Net
-- Compatível com: MySQL 8+ e PostgreSQL 13+
-- ============================================================
-- NOTA: Nomes de paradas normalizados sem acentuação para
--       compatibilidade com collation MySQL (accent-insensitive).
-- ============================================================

/*CREATE DATABASE Buss_On;

USE Buss_On;*/

-- ------------------------------------------------------------
-- SEÇÃO 0: CONFIGURAÇÃO
-- ------------------------------------------------------------
SET NAMES utf8mb4;
SET foreign_key_checks = 0;

-- ------------------------------------------------------------
-- SEÇÃO 1: CRIAÇÃO DAS TABELAS
-- ------------------------------------------------------------
DROP TABLE IF EXISTS line_document;
DROP TABLE IF EXISTS schedules;
DROP TABLE IF EXISTS itinerary_stops;
DROP TABLE IF EXISTS itineraries;
DROP TABLE IF EXISTS stops;
DROP TABLE IF EXISTS `lines`;
DROP TABLE IF EXISTS documents;
DROP TABLE IF EXISTS operators;

CREATE TABLE operators (
    operator_id   BIGINT       NOT NULL AUTO_INCREMENT,
    name          VARCHAR(100) NOT NULL,
    notes         TEXT         NULL,
    created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_operators PRIMARY KEY (operator_id),
    CONSTRAINT uq_operators_name UNIQUE (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `lines` (
    line_id       BIGINT       NOT NULL AUTO_INCREMENT,
    operator_id   BIGINT       NOT NULL,
    code          VARCHAR(50)  NULL,
    name          VARCHAR(255) NOT NULL,
    description   TEXT         NULL,
    start_date    DATE         NULL,
    active        TINYINT(1)   NOT NULL DEFAULT 1,
    created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_lines PRIMARY KEY (line_id),
    CONSTRAINT fk_lines_operator FOREIGN KEY (operator_id) REFERENCES operators(operator_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE itineraries (
    itinerary_id  BIGINT       NOT NULL AUTO_INCREMENT,
    line_id       BIGINT       NOT NULL,
    direction     VARCHAR(10)  NOT NULL COMMENT 'IDA, VOLTA ou CIRCULAR',
    variant_name  VARCHAR(200) NULL     COMMENT 'Ex: VIA SABOO, VIA AEROPORTO',
    notes         TEXT         NULL,
    created_at    TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_itineraries PRIMARY KEY (itinerary_id),
    CONSTRAINT fk_itineraries_line FOREIGN KEY (line_id) REFERENCES `lines`(line_id),
    CONSTRAINT chk_itineraries_direction CHECK (direction IN ('IDA','VOLTA','CIRCULAR'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE stops (
    stop_id       BIGINT        NOT NULL AUTO_INCREMENT,
    name          VARCHAR(255)  NOT NULL,
    stop_type     VARCHAR(50)   NULL     COMMENT 'terminal, parada, ponto_final, retorno',
    latitude      DECIMAL(10,7) NULL,
    longitude     DECIMAL(10,7) NULL,
    external_code VARCHAR(50)   NULL,
    created_at    TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_stops PRIMARY KEY (stop_id),
    CONSTRAINT uq_stops_name UNIQUE (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE itinerary_stops (
    itinerary_stop_id BIGINT NOT NULL AUTO_INCREMENT,
    itinerary_id      BIGINT NOT NULL,
    stop_id           BIGINT NOT NULL,
    stop_order        INT    NOT NULL COMMENT 'Ordem sequencial no percurso',
    arrival_offset_min INT   NULL,
    dwell_seconds      INT   NULL,
    CONSTRAINT pk_itinerary_stops PRIMARY KEY (itinerary_stop_id),
    CONSTRAINT fk_itstops_itinerary FOREIGN KEY (itinerary_id) REFERENCES itineraries(itinerary_id),
    CONSTRAINT fk_itstops_stop      FOREIGN KEY (stop_id)      REFERENCES stops(stop_id),
    CONSTRAINT uq_itstops_order     UNIQUE (itinerary_id, stop_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE schedules (
    schedule_id    BIGINT      NOT NULL AUTO_INCREMENT,
    itinerary_id   BIGINT      NOT NULL,
    departure_time TIME        NOT NULL COMMENT 'Horário de partida do ponto inicial',
    service_days   VARCHAR(20) NOT NULL COMMENT 'MON-FRI | MON-SAT | SAT | SUN-HOL | DAILY',
    notes          TEXT        NULL     COMMENT 'Descrição completa da viagem',
    is_peak        TINYINT(1)  NOT NULL DEFAULT 0,
    created_at     TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_schedules PRIMARY KEY (schedule_id),
    CONSTRAINT fk_schedules_itinerary FOREIGN KEY (itinerary_id) REFERENCES itineraries(itinerary_id),
    CONSTRAINT chk_schedules_service  CHECK (service_days IN ('MON-FRI','MON-SAT','SAT','SUN-HOL','DAILY'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE documents (
    document_id    BIGINT       NOT NULL AUTO_INCREMENT,
    title          VARCHAR(255) NOT NULL,
    effective_date DATE         NULL,
    file_reference VARCHAR(255) NULL,
    notes          TEXT         NULL,
    created_at     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_documents PRIMARY KEY (document_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE line_document (
    line_document_id BIGINT NOT NULL AUTO_INCREMENT,
    line_id          BIGINT NOT NULL,
    document_id      BIGINT NOT NULL,
    CONSTRAINT pk_line_document PRIMARY KEY (line_document_id),
    CONSTRAINT fk_ldoc_line     FOREIGN KEY (line_id)     REFERENCES `lines`(line_id),
    CONSTRAINT fk_ldoc_document FOREIGN KEY (document_id) REFERENCES documents(document_id),
    CONSTRAINT uq_line_document UNIQUE (line_id, document_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- SEÇÃO 2: ÍNDICES
-- ------------------------------------------------------------
CREATE INDEX idx_lines_operator        ON `lines`(operator_id);
CREATE INDEX idx_lines_name            ON `lines`(name);
CREATE INDEX idx_itineraries_line      ON itineraries(line_id);
CREATE INDEX idx_itineraries_line_dir  ON itineraries(line_id, direction);
CREATE INDEX idx_itstops_itinerary     ON itinerary_stops(itinerary_id);
CREATE INDEX idx_itstops_stop          ON itinerary_stops(stop_id);
CREATE INDEX idx_itstops_itin_order    ON itinerary_stops(itinerary_id, stop_order);
CREATE INDEX idx_schedules_itinerary   ON schedules(itinerary_id);
CREATE INDEX idx_schedules_time        ON schedules(itinerary_id, departure_time);
CREATE INDEX idx_schedules_days        ON schedules(service_days);

SET foreign_key_checks = 1;

