-- ------------------------------------------------------------
-- SEÇÃO 11: VIEWS
-- ------------------------------------------------------------

CREATE OR REPLACE VIEW vw_linhas_resumo AS
SELECT
    o.name                            AS operadora,
    l.line_id,
    l.name                            AS linha,
    l.start_date                      AS vigencia_inicio,
    COUNT(DISTINCT i.itinerary_id)    AS total_itinerarios,
    COUNT(DISTINCT s.schedule_id)     AS total_horarios,
    l.active                          AS ativa
FROM `lines` l
JOIN operators o        ON o.operator_id   = l.operator_id
LEFT JOIN itineraries i ON i.line_id       = l.line_id
LEFT JOIN schedules s   ON s.itinerary_id  = i.itinerary_id
GROUP BY o.name, l.line_id, l.name, l.start_date, l.active;

CREATE OR REPLACE VIEW vw_percurso_completo AS
SELECT
    l.name          AS linha,
    i.direction     AS direcao,
    i.variant_name  AS variante,
    ist.stop_order  AS ordem,
    st.name         AS parada,
    st.stop_type    AS tipo_parada
FROM itineraries i
JOIN `lines` l              ON l.line_id       = i.line_id
JOIN itinerary_stops ist  ON ist.itinerary_id = i.itinerary_id
JOIN stops st             ON st.stop_id       = ist.stop_id
ORDER BY l.name, i.direction, i.variant_name, ist.stop_order;

CREATE OR REPLACE VIEW vw_horarios AS
SELECT
    l.name           AS linha,
    i.direction      AS direcao,
    i.variant_name   AS variante,
    s.service_days   AS dias_operacao,
    s.departure_time AS horario_partida,
    s.notes          AS descricao
FROM schedules s
JOIN itineraries i ON i.itinerary_id = s.itinerary_id
JOIN `lines` l       ON l.line_id      = i.line_id
ORDER BY l.name, i.direction, s.service_days, s.departure_time;

-- ------------------------------------------------------------
-- EXEMPLOS DE CONSULTAS
-- ------------------------------------------------------------
-- Percurso de uma linha:
SELECT ordem, parada, tipo_parada FROM vw_percurso_completo
WHERE linha = 'RODOVIARIA X CANGUERA' AND direcao = 'IDA';
--
-- Horários Seg-Sex de uma linha:
SELECT horario_partida, variante FROM vw_horarios
WHERE linha = 'RODOVIARIA X CANGUERA'
AND direcao = 'IDA' AND dias_operacao IN ('MON-FRI','MON-SAT')
ORDER BY horario_partida;
